const SIKH_INFO={id:"sikh-empire-coinage",title:"Sikh Empire Coinage (Nanakshahi & Gobindshahi)",ruler:"Maharaja Ranjit Singh & Sovereign Khalsa Raj",reignPeriod:"1799 – 1849 CE (Sikh Empire)",primaryMints:"Lahore (Dar al-Saltanat), Amritsar (Sri Ambarsar), Multan, Peshawar, Kashmir",sacredMotto:"Deg Tegh Fateh (Hospitality, Protection, Victory)",keyMotif:"Peepal Leaf (Trishul/Leaf Emblem) & Mor Shahi Peacock Feather",quickStats:[{label:"Sovereign Rule",value:"Sikh Empire",icon:"⚔️"},{label:"Primary Currency",value:"Nanakshahi Rupee",icon:"🪙"},{label:"Famous Motto",value:"Deg Tegh Fateh",icon:"✨"},{label:"Primary Mint",value:"Lahore & Amritsar",icon:"🏛️"},{label:"Emblem Motif",value:"Peepal Leaf",icon:"🍃"},{label:"Metal Standard",value:"Pure Silver & Gold",icon:"⚜️"}]},COIN_EXAMPLES=[{id:"lahore-nanakshahi-rupee",name:"Lahore Nanakshahi Silver Rupee",mint:"Lahore Mint (Dar al-Saltanat)",metal:"Silver (11.1 grams, 0.980 fineness)",era:"VS 1858 (1801 CE Coronation Year)",inscription:"Deg Tegh Fateh Nusrat Bedangrai / Yaft Az Nanak Guru Gobind Singh (Kettle, Sword, Victory received from Nanak to Guru Gobind Singh)",reverseText:"Zarb Dar al-Saltanat Lahore - Sambat 1858",significance:"Standard imperial currency struck on Maharaja Ranjit Singh's coronation at Lahore, bearing no ruler name out of humility to the Gurus.",motif:"Peepal Leaf Emblem & Persian Script"},{id:"amritsar-mor-shahi-rupee",name:"Amritsar Mor Shahi Silver Rupee",mint:"Amritsar Mint (Sri Ambarsar)",metal:"Silver (11.0 grams)",era:"VS 1863 (1806 CE)",inscription:"Sikka Zad Bar Har Do Alam Fazl Sachha Sahib Ast / Fath Gobind Singh Shah-i-Shahan Fazl Nanak Sahib Ast",reverseText:"Zarb Sri Ambarsar Jiyo - Sambat 1863 with Peacock Tail / Feather Motif",significance:"Minted in the holy city of Amritsar, famous for incorporating the delicate Mor (peacock feather) mintmark.",motif:"Mor Shahi Peacock Feather"},{id:"multan-nanakshahi-rupee",name:"Multan Nanakshahi Silver Rupee",mint:"Multan Mint (Dar al-Aman)",metal:"Silver (11.0 grams)",era:"VS 1875 (1818 CE)",inscription:"Deg Tegh Fateh Nusrat Bedangrai",reverseText:"Zarb Multan Dar al-Aman - Sambat 1875",significance:"Issued following Diwan Mokham Chand and Prince Kharak Singh's conquest of Multan.",motif:"Katar Dagger & Peepal Leaf"},{id:"gold-nanakshahi-mohur",name:"Gold Nanakshahi Mohur",mint:"Lahore Mint",metal:"Gold (12.0 grams, 0.990 pure gold)",era:"VS 1893 (1836 CE)",inscription:"Deg Tegh Fateh Nusrat Bedangrai / Yaft Az Nanak Guru Gobind Singh",reverseText:"Zarb Dar al-Saltanat Lahore - Sambat 1893",significance:"Extremely rare gold ceremonial coin used for royal offerings at Harmandir Sahib (Golden Temple).",motif:"Royal Imperial Sunburst & Peepal Leaf"}],INSCRIPTION_BREAKDOWN=[{phrase:"Deg (دیگ)",meaning:"The Kettle / Cauldron",significance:"Symbolizes free community kitchen (Langar), hospitality, and social equality."},{phrase:"Tegh (تیغ)",meaning:"The Sword",significance:"Symbolizes protection of the oppressed, justice, and defense of freedom."},{phrase:"Fateh (فتح)",meaning:"Victory",significance:"Symbolizes ultimate spiritual and political victory unhindered (Nusrat Bedangrai)."},{phrase:"Yaft Az Nanak Guru Gobind Singh",meaning:"Received from Guru Nanak to Guru Gobind Singh",significance:"Acknowledges all authority and sovereignty as bestowed by the Sikh Gurus, not the individual monarch."}],SIKH_MINTS=[{name:"Lahore (Dar al-Saltanat)",location:"Capital City, Punjab",description:"Primary royal mint striking standard high-purity Nanakshahi silver rupees and gold mohurs."},{name:"Amritsar (Sri Ambarsar Jiyo)",location:"Holy City, Punjab",description:"Religious mint located near Harmandir Sahib, producing Mor Shahi and Arsee Shahi coin series."},{name:"Multan (Dar al-Aman)",location:"Southern Punjab / Sindh",description:"Fortress mint established after 1818 CE, circulating throughout western trade routes."},{name:"Peshawar & Kashmir",location:"Frontier Provinces",description:"Frontier mints striking regional coins managed by General Hari Singh Nalwa."}],TIMELINE_EVENTS=[{year:"1765 CE (VS 1822)",title:"First Sikh Coinage of Dal Khalsa",description:"Sikh Misls liberate Lahore from Afghan invaders and strike the first Gobindshahi silver rupees."},{year:"1799 CE",title:"Conquest of Lahore",description:"Maharaja Ranjit Singh captures Lahore, unifying the Sikh Misls into a sovereign empire."},{year:"1801 CE (VS 1858)",title:"Coronation & Nanakshahi Standard",description:"Ranjit Singh assumes title of Maharaja and strikes imperial Nanakshahi rupees bearing the Peepal leaf motif."},{year:"1849 CE",title:"Annexation of Punjab",description:"Second Anglo-Sikh War ends; Sikh Empire coinage retired and replaced by British East India Company rupees."}],REFERENCES=[{text:"Herrli, Hans (2004). The Coins of the Sikhs. Munshiram Manoharlal Publishers.",link:"#"},{text:"Singh, Gurprit (2012). Nanakshahi & Gobindshahi Coins of the Sikh Empire. Heritage Numismatics.",link:"#"},{text:"Surinder Singh (2004). Sikh Coinage: Symbol of Sovereign Power. Manohar Publications.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={SIKH_INFO:SIKH_INFO,COIN_EXAMPLES:COIN_EXAMPLES,INSCRIPTION_BREAKDOWN:INSCRIPTION_BREAKDOWN,SIKH_MINTS:SIKH_MINTS,TIMELINE_EVENTS:TIMELINE_EVENTS,REFERENCES:REFERENCES});